export const SPECIES_NAMES_BY_LANGUAGE = Object.freeze({
  1: JAPANESE_SPECIES_NAMES,
  2: ENGLISH_SPECIES_NAMES,
  3: FRENCH_SPECIES_NAMES,
  4: ENGLISH_SPECIES_NAMES,
  5: GERMAN_SPECIES_NAMES,
  7: ENGLISH_SPECIES_NAMES,
});

export function getLocalizedSpeciesName(speciesId, languageId) {
  const id = Number(speciesId);
  const names = SPECIES_NAMES_BY_LANGUAGE[Number(languageId)] || ENGLISH_SPECIES_NAMES;
  return names[id] || ENGLISH_SPECIES_NAMES[id] || '';
}
